import{_ as t,c as a,o as e,b0 as d}from"./chunks/framework.C5ev1SXp.js";const I="data:image/svg+xml;base64,",o="data:image/svg+xml;base64,",p=JSON.parse('{"title":"LV004-任务控制块","description":null,"frontmatter":{"title":"LV004-任务控制块","date":"2026-11-18T18:40:36.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/rtos/rtos-task/126d68c08a642de71536630d","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-11-18T18:40:36.734Z","fulluuid":"71536630d8454b8097faf5190ce48f35","useduuid":"71536630d"}},"headers":[],"relativePath":"sdoc/advanced-chapter/rtos/rtos-task/126d68c08a642de71536630d.md","filePath":"sdoc/30-进阶篇/90-FreeRTOS/02-任务管理/LV004-任务控制块.md","lastUpdated":1795000891000}'),s={name:"sdoc/advanced-chapter/rtos/rtos-task/126d68c08a642de71536630d.md"};function l(c,i,h,r,n,g){return e(),a("div",null,[...i[0]||(i[0]=[d(`<h1 id="lv004-任务控制块" tabindex="-1">LV004-任务控制块 <a class="header-anchor" href="#lv004-任务控制块" aria-label="Permalink to &quot;LV004-任务控制块&quot;">​</a></h1><h2 id="一、-tcb-是什么" tabindex="-1">一、 TCB 是什么 <a class="header-anchor" href="#一、-tcb-是什么" aria-label="Permalink to &quot;一、 TCB 是什么&quot;">​</a></h2><h3 id="_1-位置、大小与来源" tabindex="-1">1. 位置、大小与来源 <a class="header-anchor" href="#_1-位置、大小与来源" aria-label="Permalink to &quot;1. 位置、大小与来源&quot;">​</a></h3><h4 id="_1-1-三个来源" tabindex="-1">1.1 三个来源 <a class="header-anchor" href="#_1-1-三个来源" aria-label="Permalink to &quot;1.1 三个来源&quot;">​</a></h4><table tabindex="0"><thead><tr><th>创建方式</th><th>TCB 从哪来</th><th>本工程实例</th></tr></thead><tbody><tr><td>动态任务</td><td><code>pvPortMalloc(96)</code>，位于 <code>ucHeap</code></td><td>defaultTask <code>0x20001730</code></td></tr><tr><td>静态任务</td><td>应用提供的 <code>StaticTask_t</code>，位于 <code>.bss</code></td><td>IDLE <code>0x20000C00</code></td></tr><tr><td>内核内部任务</td><td>同上（静态）</td><td>Tmr Svc <code>0x20000E60</code></td></tr></tbody></table><h4 id="_1-2-96-字节的构成" tabindex="-1">1.2 96 字节的构成 <a class="header-anchor" href="#_1-2-96-字节的构成" aria-label="Permalink to &quot;1.2 96 字节的构成&quot;">​</a></h4><p><code>configMAX_TASK_NAME_LEN = 16</code>、<code>configUSE_TASK_NOTIFICATIONS = 1</code>、<code>configGENERATE_RUN_TIME_STATS = 1</code>，这几项配置直接决定了 TCB 的大小。本工程实测 <strong>96 字节</strong>：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>字节</th><th>偏移（约）</th></tr></thead><tbody><tr><td><code>pxTopOfStack</code></td><td>指针</td><td>4</td><td>0</td></tr><tr><td><code>xStateListItem</code></td><td><code>ListItem_t</code></td><td>20</td><td>4</td></tr><tr><td><code>xEventListItem</code></td><td><code>ListItem_t</code></td><td>20</td><td>24</td></tr><tr><td><code>uxPriority</code></td><td><code>UBaseType_t</code></td><td>4</td><td>44</td></tr><tr><td><code>pxStack</code></td><td>指针</td><td>4</td><td>48</td></tr><tr><td><code>pcTaskName[16]</code></td><td><code>char</code></td><td>16</td><td>52</td></tr><tr><td><code>uxBasePriority</code></td><td><code>UBaseType_t</code></td><td>4</td><td>68</td></tr><tr><td><code>uxMutexesHeld</code></td><td><code>UBaseType_t</code></td><td>4</td><td>72</td></tr><tr><td><code>ulNotifiedValue</code></td><td><code>uint32_t</code></td><td>4</td><td>76</td></tr><tr><td><code>ucNotifyState</code></td><td><code>uint8_t</code></td><td>1+3</td><td>80</td></tr><tr><td><code>uxTCBNumber</code> / <code>uxTaskNumber</code></td><td><code>UBaseType_t</code></td><td>8</td><td>84</td></tr><tr><td><code>ulRunTimeCounter</code></td><td><code>uint32_t</code></td><td>4</td><td>92</td></tr><tr><td><code>ucStaticallyAllocated</code></td><td><code>uint8_t</code></td><td>1+3</td><td>96 之前</td></tr></tbody></table><p>差不多 96 字节——比很多人的直觉要小，因为它只放&quot;调度必需&quot;的信息，业务数据一律不进 TCB。</p><h3 id="_2-为什么需要它" tabindex="-1">2. 为什么需要它 <a class="header-anchor" href="#_2-为什么需要它" aria-label="Permalink to &quot;2. 为什么需要它&quot;">​</a></h3><p>任务函数是只读代码，本身没有任何身份。内核要回答四个问题，全在 TCB 里：</p><ul><li><strong>该不该跑</strong>：<code>uxPriority</code> + 所在链表</li><li><strong>从哪继续</strong>：<code>pxTopOfStack</code></li><li><strong>栈有没有踩线</strong>：<code>pxStack</code></li><li><strong>叫什么、跑了多久</strong>：<code>pcTaskName</code> + <code>ulRunTimeCounter</code></li></ul><h3 id="_3-tcb-的生命周期" tabindex="-1">3. TCB 的生命周期 <a class="header-anchor" href="#_3-tcb-的生命周期" aria-label="Permalink to &quot;3. TCB 的生命周期&quot;">​</a></h3><h4 id="_3-1-创建" tabindex="-1">3.1 创建 <a class="header-anchor" href="#_3-1-创建" aria-label="Permalink to &quot;3.1 创建&quot;">​</a></h4><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Source/tasks.c（简化）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pxNewTCB </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">TCB_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pvPortMalloc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">TCB_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pxNewTCB</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pxStack </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">StackType_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pvPortMalloc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(depth </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prvInitialiseNewTask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(...);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        /* 填名字、优先级、栈指针 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prvAddNewTaskToReadyList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(pxNewTCB);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  /* 挂到就绪链表 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h4 id="_3-2-运行" tabindex="-1">3.2 运行 <a class="header-anchor" href="#_3-2-运行" aria-label="Permalink to &quot;3.2 运行&quot;">​</a></h4><p>切换时只改三个东西：<code>pxTopOfStack</code>（保存/恢复现场）、链表归属（状态变化）、<code>pxCurrentTCB</code>（指向当前任务）。</p><h4 id="_3-3-删除" tabindex="-1">3.3 删除 <a class="header-anchor" href="#_3-3-删除" aria-label="Permalink to &quot;3.3 删除&quot;">​</a></h4><p><code>vTaskDelete()</code> 把它从链表摘除；动态任务的 TCB 与栈由 <code>prvDeleteTCB()</code> 归还堆，静态任务的内存原地不动。</p><p><img src="`+I+'" alt="TCB 的字段分组"></p><h2 id="二、-字段详解" tabindex="-1">二、 字段详解 <a class="header-anchor" href="#二、-字段详解" aria-label="Permalink to &quot;二、 字段详解&quot;">​</a></h2><h3 id="_1-栈相关" tabindex="-1">1. 栈相关 <a class="header-anchor" href="#_1-栈相关" aria-label="Permalink to &quot;1. 栈相关&quot;">​</a></h3><h4 id="_1-1-pxtopofstack" tabindex="-1">1.1 pxTopOfStack <a class="header-anchor" href="#_1-1-pxtopofstack" aria-label="Permalink to &quot;1.1 pxTopOfStack&quot;">​</a></h4><p>当前栈顶，<strong>每次切换都会被改写</strong>。PendSV 里执行 <code>mrs r0, psp</code> 拿到当前值并存回旧任务，再把新任务的值 <code>msr psp, r0</code> 写回。</p><h4 id="_1-2-pxstack" tabindex="-1">1.2 pxStack <a class="header-anchor" href="#_1-2-pxstack" aria-label="Permalink to &quot;1.2 pxStack&quot;">​</a></h4><p>栈底（最低地址），<strong>创建后恒定不变</strong>。它有两个用途：栈溢出检测的起点、<code>uxTaskGetStackHighWaterMark()</code> 的计算基准。</p><p>两者关系：<code>pxTopOfStack</code> 在 <code>pxStack</code> 之上浮动，差值就是当前已用的栈空间。</p><h3 id="_2-链表项" tabindex="-1">2. 链表项 <a class="header-anchor" href="#_2-链表项" aria-label="Permalink to &quot;2. 链表项&quot;">​</a></h3><h4 id="_2-1-xstatelistitem" tabindex="-1">2.1 xStateListItem <a class="header-anchor" href="#_2-1-xstatelistitem" aria-label="Permalink to &quot;2.1 xStateListItem&quot;">​</a></h4><p>挂在三条状态链表之一（就绪 / 延时 / 挂起）。<strong>任务同一时刻只能处于一种状态</strong>，所以只需要一个这样的项。</p><h4 id="_2-2-xeventlistitem" tabindex="-1">2.2 xEventListItem <a class="header-anchor" href="#_2-2-xeventlistitem" aria-label="Permalink to &quot;2.2 xEventListItem&quot;">​</a></h4><p>等队列、信号量、事件组时，挂到目标对象的事件链表上。它与状态链表项同时存在，互不冲突——这就是&quot;一个任务在等某个信号量的同时仍是阻塞态&quot;的实现方式。</p><h4 id="_2-3-xitemvalue" tabindex="-1">2.3 xItemValue <a class="header-anchor" href="#_2-3-xitemvalue" aria-label="Permalink to &quot;2.3 xItemValue&quot;">​</a></h4><p>每个链表项里有个 <code>xItemValue</code>，含义随链表变化：</p><table tabindex="0"><thead><tr><th>链表</th><th>xItemValue 的含义</th></tr></thead><tbody><tr><td>就绪链表</td><td>任务的优先级</td></tr><tr><td>延时链表</td><td>唤醒时刻（绝对 tick）</td></tr><tr><td>事件链表</td><td>等待顺序或事件优先级</td></tr></tbody></table><p>因为链表按 <code>xItemValue</code> 有序，插入与查找都不需要遍历全部节点。</p><h3 id="_3-优先级" tabindex="-1">3. 优先级 <a class="header-anchor" href="#_3-优先级" aria-label="Permalink to &quot;3. 优先级&quot;">​</a></h3><h4 id="_3-1-uxpriority" tabindex="-1">3.1 uxPriority <a class="header-anchor" href="#_3-1-uxpriority" aria-label="Permalink to &quot;3.1 uxPriority&quot;">​</a></h4><p>当前生效的优先级，抢占与轮转都看它。</p><h4 id="_3-2-uxbasepriority-与优先级继承" tabindex="-1">3.2 uxBasePriority 与优先级继承 <a class="header-anchor" href="#_3-2-uxbasepriority-与优先级继承" aria-label="Permalink to &quot;3.2 uxBasePriority 与优先级继承&quot;">​</a></h4><p>创建时的原始值。当任务持有互斥量、被更高优先级任务等待时，内核会把它的 <code>uxPriority</code> 临时抬到等待者的优先级；释放互斥量后，用 <code>uxBasePriority</code> 恢复。</p><p>这正是&quot;优先级反转&quot;的解法，细节见 <a href="./../03-内存管理/LV001-任务栈与主栈.html">LV001-任务栈与主栈</a> 之外的调度资料。</p><h4 id="_3-3-uxmutexesheld" tabindex="-1">3.3 uxMutexesHeld <a class="header-anchor" href="#_3-3-uxmutexesheld" aria-label="Permalink to &quot;3.3 uxMutexesHeld&quot;">​</a></h4><p>记录该任务当前持有多少把互斥量，用于判断是否需要恢复优先级。</p><h3 id="_4-标识" tabindex="-1">4. 标识 <a class="header-anchor" href="#_4-标识" aria-label="Permalink to &quot;4. 标识&quot;">​</a></h3><h4 id="_4-1-pctaskname" tabindex="-1">4.1 pcTaskName <a class="header-anchor" href="#_4-1-pctaskname" aria-label="Permalink to &quot;4.1 pcTaskName&quot;">​</a></h4><p>最多 15 个字符（<code>configMAX_TASK_NAME_LEN = 16</code> 含结尾 <code>\\0</code>）。<code>ps</code> 命令的第一列就来自这里。</p><h4 id="_4-2-uxtcbnumber-与-uxtasknumber" tabindex="-1">4.2 uxTCBNumber 与 uxTaskNumber <a class="header-anchor" href="#_4-2-uxtcbnumber-与-uxtasknumber" aria-label="Permalink to &quot;4.2 uxTCBNumber 与 uxTaskNumber&quot;">​</a></h4><p>前者在创建时分配、删除后回收；后者在任务优先级等属性变化时递增。两者主要服务于调试器与统计，普通代码不会用到。</p><h3 id="_5-其它" tabindex="-1">5. 其它 <a class="header-anchor" href="#_5-其它" aria-label="Permalink to &quot;5. 其它&quot;">​</a></h3><h4 id="_5-1-通知值" tabindex="-1">5.1 通知值 <a class="header-anchor" href="#_5-1-通知值" aria-label="Permalink to &quot;5.1 通知值&quot;">​</a></h4><p><code>ulNotifiedValue</code> + <code>ucNotifyState</code> 实现&quot;任务通知&quot;：可以当二值信号量、计数信号量、事件标志甚至邮箱用，开销比队列小得多。</p><p><code>ucNotifyState</code> 有三种取值：未等待、正在等待、已收到通知。</p><h4 id="_5-2-ucstaticallyallocated" tabindex="-1">5.2 ucStaticallyAllocated <a class="header-anchor" href="#_5-2-ucstaticallyallocated" aria-label="Permalink to &quot;5.2 ucStaticallyAllocated&quot;">​</a></h4><p>标记栈与 TCB 是否为静态分配。删除任务时内核据此决定&quot;要不要 <code>vPortFree</code>&quot;——静态任务的内存不能由内核释放。</p><h4 id="_5-3-ulruntimecounter" tabindex="-1">5.3 ulRunTimeCounter <a class="header-anchor" href="#_5-3-ulruntimecounter" aria-label="Permalink to &quot;5.3 ulRunTimeCounter&quot;">​</a></h4><p>累计运行时间，单位由 <code>portGET_RUN_TIME_COUNTER_VALUE()</code> 决定。本工程用 DWT 折算成 0.1 ms，<code>top</code> 命令的百分比就是拿它除以统计窗口得到的。</p><h2 id="三、-状态由链表表达" tabindex="-1">三、 状态由链表表达 <a class="header-anchor" href="#三、-状态由链表表达" aria-label="Permalink to &quot;三、 状态由链表表达&quot;">​</a></h2><p><img src="'+o+`" alt="TCB 挂在哪些链表上"></p><h3 id="_1-就绪链表是数组" tabindex="-1">1. 就绪链表是数组 <a class="header-anchor" href="#_1-就绪链表是数组" aria-label="Permalink to &quot;1. 就绪链表是数组&quot;">​</a></h3><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Source/tasks.c</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PRIVILEGED_DATA </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">static</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> List_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> pxReadyTasksLists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[ configMAX_PRIORITIES ];</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>本工程 <code>configMAX_PRIORITIES = 56</code>，所以是 56 条链表组成的数组。任务就绪时挂到&quot;自己优先级&quot;那条上。</p><p>调度器选下一个任务的动作因此极简：从最高优先级往下找第一条非空链表，取表头。</p><h3 id="_2-延时链表与溢出链表" tabindex="-1">2. 延时链表与溢出链表 <a class="header-anchor" href="#_2-延时链表与溢出链表" aria-label="Permalink to &quot;2. 延时链表与溢出链表&quot;">​</a></h3><p>延时链表按唤醒时刻排序，节拍中断只检查表头即可判断&quot;有没有任务该醒了&quot;。</p><p>因为 tick 是 32 位无符号、会回绕，FreeRTOS 用了两条链表：<code>pxDelayedTaskList</code> 与 <code>pxOverflowDelayedTaskList</code>，跨越回绕点时在两者之间搬移。</p><h3 id="_3-挂起链表" tabindex="-1">3. 挂起链表 <a class="header-anchor" href="#_3-挂起链表" aria-label="Permalink to &quot;3. 挂起链表&quot;">​</a></h3><p>与时间无关，只能被 <code>osThreadResume()</code> 显式唤醒。</p><h3 id="_4-pxcurrenttcb" tabindex="-1">4. pxCurrentTCB <a class="header-anchor" href="#_4-pxcurrenttcb" aria-label="Permalink to &quot;4. pxCurrentTCB&quot;">​</a></h3><p>一个全局指针，指向正在运行的任务。切换的本质就是&quot;改这个指针 + 换 PSP&quot;。</p><h3 id="_5-为什么没有-estate-字段" tabindex="-1">5. 为什么没有 eState 字段 <a class="header-anchor" href="#_5-为什么没有-estate-字段" aria-label="Permalink to &quot;5. 为什么没有 eState 字段&quot;">​</a></h3><p>很多人找 <code>eState</code>，但 FreeRTOS 里没有——状态<strong>隐含在链表归属</strong>里。<code>uxTaskGetSystemState()</code> 内部也是遍历各条链表反推状态，再填进 <code>TaskStatus_t.eCurrentState</code>。</p><h2 id="四、-观察与验证" tabindex="-1">四、 观察与验证 <a class="header-anchor" href="#四、-观察与验证" aria-label="Permalink to &quot;四、 观察与验证&quot;">​</a></h2><h3 id="_1-ps-的每个字段来源" tabindex="-1">1. ps 的每个字段来源 <a class="header-anchor" href="#_1-ps-的每个字段来源" aria-label="Permalink to &quot;1. ps 的每个字段来源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ps 列</th><th>TCB 字段</th></tr></thead><tbody><tr><td><code>NAME</code></td><td><code>pcTaskName</code></td></tr><tr><td><code>STATE</code></td><td>由&quot;挂在哪条链表&quot;反推</td></tr><tr><td><code>PRIO</code></td><td><code>uxPriority</code></td></tr><tr><td><code>FREE</code></td><td><code>pxStack</code> 向上的 <code>0xA5</code> 计数</td></tr></tbody></table><h3 id="_2-从堆里-dump-一个-tcb" tabindex="-1">2. 从堆里 dump 一个 TCB <a class="header-anchor" href="#_2-从堆里-dump-一个-tcb" aria-label="Permalink to &quot;2. 从堆里 dump 一个 TCB&quot;">​</a></h3><p>TCB 就在 <code>ucHeap</code> 里，按 8 字节块头定位即可。本工程 shellTask 的 TCB 位于 <code>0x20002208</code>（块首），用户区从 <code>0x20002210</code> 开始，96 字节长。前 4 字节是 <code>pxTopOfStack</code>，接着是 20 字节的状态链表项。</p><h3 id="_3-相关配置宏" tabindex="-1">3. 相关配置宏 <a class="header-anchor" href="#_3-相关配置宏" aria-label="Permalink to &quot;3. 相关配置宏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>宏</th><th>作用</th><th>本工程</th></tr></thead><tbody><tr><td><code>configUSE_TRACE_FACILITY</code></td><td>提供 <code>uxTaskGetSystemState()</code></td><td>1</td></tr><tr><td><code>configCHECK_FOR_STACK_OVERFLOW</code></td><td>2 时切换中扫描 <code>0xA5</code></td><td>2</td></tr><tr><td><code>configRECORD_STACK_HIGH_ADDRESS</code></td><td>记录 <code>pxEndOfStack</code></td><td>未开</td></tr><tr><td><code>configGENERATE_RUN_TIME_STATS</code></td><td>提供 <code>ulRunTimeCounter</code></td><td>1</td></tr><tr><td><code>configUSE_TASK_NOTIFICATIONS</code></td><td>提供通知字段</td><td>1（默认）</td></tr><tr><td><code>configMAX_TASK_NAME_LEN</code></td><td>名字缓冲区长度</td><td>16</td></tr></tbody></table><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,81)])])}const m=t(s,[["render",l]]);export{p as __pageData,m as default};
